insert into questoes (id,materia,topico,tipo,enunciado,alternativas,aluno) values
  ('hist-t01','historia','Módulo 13: Brasil, a encruzilhada da ditadura','treino','A expressão "anos de chumbo" se refere ao período da ditadura militar marcado por:','["Grande liberdade de imprensa", "Repressão mais violenta, censura e perseguição a opositores, sobretudo no governo Médici", "Eleições diretas para presidente", "Fim do AI-5 e anistia aos presos políticos"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('hist-t02','historia','Módulo 13: Brasil, a encruzilhada da ditadura','treino','Por que a crise do petróleo de 1973 afetou tanto o Brasil?','["O Brasil era o maior exportador de petróleo do mundo", "O petróleo ficou muito mais barato", "O país dependia de petróleo importado, e o preço subiu muito em poucos meses", "O Brasil não usava petróleo naquela época"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('hist-t03','historia','Módulo 13: Brasil, a encruzilhada da ditadura','treino','O que é estagflação?','["Crescimento rápido da economia com preços em queda", "Estagnação da economia junto com inflação alta", "O fim da inflação", "Aumento rápido das exportações"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('hist-t04','historia','Módulo 13: Brasil, a encruzilhada da ditadura','treino','O período de forte crescimento do PIB no início dos anos 1970, durante a ditadura, ficou conhecido como:','["Década perdida", "Plano Real", "Diretas Já", "Milagre econômico"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('hist-t05','historia','Módulo 13: Brasil, a encruzilhada da ditadura','treino','As greves de 1978 a 1980 na região do ABC paulista (Santo André, São Bernardo e São Caetano) foram feitas principalmente por:','["Fazendeiros contra a reforma agrária", "Militares da linha-dura", "Banqueiros contra a inflação", "Metalúrgicos, com destaque para o líder sindical Lula"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('hist-t06','historia','Módulo 13: Brasil, a encruzilhada da ditadura','treino','A Guerrilha do Araguaia foi organizada:','["Por militares contra o presidente Médici", "Pelo PCdoB, na região do Bico do Papagaio, buscando o apoio dos camponeses", "Por fazendeiros de São Paulo contra impostos", "Por estudantes que ocuparam Brasília"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('hist-t07','historia','Módulo 13: Brasil, a encruzilhada da ditadura','treino','O assassinato do jornalista Vladimir Herzog, em São Paulo, em 1975, provocou:','["O fortalecimento imediato da linha-dura", "O fim da censura no mesmo dia", "A união de vários setores da sociedade contra a tortura e a repressão", "O início da Guerrilha do Araguaia"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('hist-t08','historia','Módulo 13: Brasil, a encruzilhada da ditadura','treino','A abertura política conduzida pelo presidente Geisel foi definida como:','["\"Rápida, total e imediata\"", "\"Lenta, gradual e segura\"", "\"Armada e revolucionária\"", "\"Popular e com eleições diretas já\""]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('hist-t09','historia','Módulo 13: Brasil, a encruzilhada da ditadura','treino','Quando o AI-5 deixou de valer?','["Em 1964, logo após o golpe", "Em 1988, com a nova Constituição", "Em 1º de janeiro de 1979, ainda no governo Geisel", "Em 1985, com a posse de Sarney"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('hist-t10','historia','Módulo 13: Brasil, a encruzilhada da ditadura','treino','Por que se diz que a Lei da Anistia de 1979 foi uma lei de "mão dupla"?','["Valia só para os militares", "Perdoou presos e exilados políticos, mas também os agentes do Estado que torturaram e mataram", "Valia só para os guerrilheiros", "Perdoava apenas quem pagasse uma multa"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('hist-t11','historia','Módulo 13: Brasil, a encruzilhada da ditadura','treino','O atentado do Riocentro, em 30 de abril de 1981, mostrou:','["A reação da linha-dura militar contra a abertura política", "A força da Guerrilha do Araguaia", "O apoio popular ao AI-5", "O fim das Forças Armadas"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('hist-t12','historia','Módulo 13: Brasil, a encruzilhada da ditadura','treino','O que pedia a campanha "Diretas Já" (1983–1984)?','["A volta do AI-5", "Eleições diretas para presidente da República", "O fechamento do Congresso", "A volta da monarquia"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('hist-t13','historia','Módulo 13: Brasil, a encruzilhada da ditadura','treino','O que aconteceu com a emenda Dante de Oliveira, em 1984?','["Não foi aprovada: faltaram 22 votos para os dois terços necessários", "Foi aprovada por unanimidade", "Criou o AI-5", "Criou o Plano Real"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('hist-t14','historia','Módulo 13: Brasil, a encruzilhada da ditadura','treino','Nas eleições para governador de 1982, a oposição venceu em estados importantes, como:','["Collor em Alagoas e Sarney no Maranhão", "Lula em São Paulo e FHC no Rio", "Médici no Rio Grande do Sul", "Brizola no Rio de Janeiro, Montoro em São Paulo e Tancredo Neves em Minas Gerais"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('hist-t15','historia','Nova República e Constituição de 1988','treino','Quem foi eleito presidente em 1985, numa eleição indireta, mas morreu antes de tomar posse?','["José Sarney", "Ulysses Guimarães", "Fernando Collor", "Tancredo Neves"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('hist-t16','historia','Nova República e Constituição de 1988','treino','Com a morte de Tancredo Neves, quem assumiu a Presidência?','["Ulysses Guimarães", "José Sarney, o vice", "João Figueiredo", "Itamar Franco"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('hist-t17','historia','Nova República e Constituição de 1988','treino','A Constituição de 1988 substituiu a Constituição de:','["1824, do Império", "1937, do Estado Novo", "1891, a primeira da República", "1967, herança do regime militar"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('hist-t18','historia','Nova República e Constituição de 1988','treino','Quando a Constituição de 1988 foi promulgada?','["Em 1º de fevereiro de 1987", "Em 15 de novembro de 1889", "Em 5 de outubro de 1988", "Em 31 de março de 1964"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('hist-t19','historia','Nova República e Constituição de 1988','treino','Quem chamou a Constituição de 1988 de "Constituição Cidadã"?','["Getúlio Vargas", "Tiradentes", "Ulysses Guimarães", "Emílio Médici"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('hist-t20','historia','Nova República e Constituição de 1988','treino','Por que a Constituição de 1988 ficou conhecida como "Constituição Cidadã"?','["Porque ampliou os direitos sociais e políticos de grande parte da sociedade", "Porque só os cidadãos ricos podiam votar", "Porque foi escrita pelos militares", "Porque acabou com as eleições"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('hist-t21','historia','Nova República e Constituição de 1988','treino','Qual destes direitos foi garantido pela Constituição de 1988?','["Voto de analfabetos e de jovens a partir de 16 anos", "Voto só para homens alfabetizados", "Censura prévia à imprensa", "Fim da liberdade de expressão"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('hist-t22','historia','Nova República e Constituição de 1988','treino','Pela Constituição de 1988, racismo e tortura são:','["Permitidos em casos especiais", "Infrações leves, punidas só com multa", "Crimes inafiançáveis", "Assuntos que a Constituição não trata"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('hist-t23','historia','Nova República e Constituição de 1988','treino','O artigo 5º da Constituição diz que todos são iguais perante a lei. Isso significa que:','["Brasileiros e estrangeiros que vivem no país têm os mesmos direitos fundamentais, sem distinção", "Só os brasileiros natos têm direitos", "Os homens têm mais direitos que as mulheres", "A lei vale só para quem é pobre"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('hist-t24','historia','A conquista do protagonismo feminino','treino','Berta Lutz é lembrada na história do Brasil porque:','["Foi a primeira presidente do Brasil", "Liderou o movimento sufragista e, em 1922, fundou uma federação pelo progresso das mulheres", "Escreveu sozinha a Constituição de 1988", "Liderou a Guerrilha do Araguaia"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('hist-t25','historia','A conquista do protagonismo feminino','treino','Quando as mulheres brasileiras conquistaram o direito de votar?','["No século XIX, com o Império", "Na década de 1930", "Só em 1988", "Em 2009, com a lei de cotas"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('hist-t26','historia','A conquista do protagonismo feminino','treino','A igualdade de direitos entre homens e mulheres, com proibição de discriminação por sexo, ficou assegurada a partir de:','["A Lei Áurea", "A Constituição de 1988", "O AI-5", "A Constituição de 1824"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('hist-t27','historia','A conquista do protagonismo feminino','treino','O que determinou a Lei nº 12.034, de 2009, sobre as candidaturas?','["Os partidos só podem lançar candidatos homens", "Metade das cadeiras do Congresso fica reservada às mulheres", "As candidaturas femininas ficam proibidas", "Cada partido deve ter no mínimo 30% e no máximo 70% de candidaturas de cada sexo"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('hist-t28','historia','A conquista do protagonismo feminino','treino','Por que tratar a política como um "espaço masculino" é considerado uma forma de violência simbólica?','["Porque é proibido por lei mulheres serem candidatas", "Porque os homens são impedidos de votar", "Porque não existe nenhuma mulher na política", "Porque faz as mulheres não serem reconhecidas como capazes de atuar na política"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('hist-t29','historia','A conquista do protagonismo feminino','treino','Que medida o texto estudado aponta como a mais adequada para corrigir a desigualdade entre homens e mulheres na política?','["Acabar com as cotas", "Proibir candidaturas masculinas", "Deixar tudo como está", "Lista alternada, com 50% das candidaturas para cada sexo"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('hist-t30','historia','Questão indígena e questão do "campo negro"','treino','O que a Constituição de 1988, no capítulo "Dos Índios", garantiu aos povos indígenas?','["O direito às terras que eles tradicionalmente ocupam", "A obrigação de deixar suas terras", "A proibição de falar suas línguas", "Nenhum direito específico"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('hist-t31','historia','Questão indígena e questão do "campo negro"','treino','Qual destes fatores dificulta a demarcação das terras indígenas?','["A falta de interesse econômico por essas terras", "A inexistência de povos indígenas no Norte", "O fim da FUNAI em 1967", "O avanço da fronteira agrícola para o Norte e o Centro-Oeste, onde vive a maior parte dos indígenas"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('hist-t32','historia','Questão indígena e questão do "campo negro"','treino','A FUNAI (Fundação Nacional do Índio), criada em 1967:','["Foi criada para explorar minérios", "Substituiu o SPI como órgão indigenista oficial do governo", "Organizava a Guerrilha do Araguaia", "Cuidava das eleições"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('hist-t33','historia','Questão indígena e questão do "campo negro"','treino','O Estatuto do Índio, de 1973, considerava os indígenas "relativamente incapazes". Isso quer dizer que:','["Eles tinham todos os direitos de um cidadão comum", "Eles podiam votar a partir dos 12 anos", "Eles ficavam sob a tutela do Estado (FUNAI) até serem \"integrados\" à sociedade", "Eles eram donos de todas as terras do país"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('hist-t34','historia','Questão indígena e questão do "campo negro"','treino','O que foram os quilombos?','["Aldeias indígenas do litoral", "Comunidades formadas por africanos escravizados que fugiam das fazendas", "Fazendas de café do século XIX", "Fortes militares portugueses"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('hist-t35','historia','Questão indígena e questão do "campo negro"','treino','O que a Constituição de 1988 reconheceu aos remanescentes das comunidades de quilombos?','["Nenhum direito", "O direito de serem levados para outras terras", "A propriedade das terras que ocupam", "A obrigação de pagar impostos especiais"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('hist-t36','historia','Questão indígena e questão do "campo negro"','treino','Quem foi o marechal ligado à criação do SPI e à defesa dos povos indígenas, que levou Vargas a criar, em 1943, o Dia do Índio (hoje Dia dos Povos Indígenas)?','["Marechal Deodoro", "Marechal Castelo Branco", "Marechal Floriano", "Marechal Rondon"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('hist-t37','historia','Transformações do capitalismo na América Latina e no Brasil','treino','O que defende o neoliberalismo?','["O Estado como dono de todas as empresas", "Fechar o país ao comércio exterior", "Menor participação do Estado na economia, privatizações e abertura ao mercado", "Aumentar a estatização e os gastos do governo"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('hist-t38','historia','Transformações do capitalismo na América Latina e no Brasil','treino','O desenvolvimentismo, que vigorou na América Latina entre os anos 1930 e 1980, era:','["Uma estratégia em que o Estado coordenava o desenvolvimento e a industrialização", "Uma proposta de reduzir o Estado ao mínimo", "Uma economia só agrícola, sem indústrias", "O socialismo soviético"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('hist-t39','historia','Transformações do capitalismo na América Latina e no Brasil','treino','Como ficou conhecida a década de 1980 na América Latina?','["Década perdida", "Milagre econômico", "Anos dourados", "Belle Époque"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('hist-t40','historia','Transformações do capitalismo na América Latina e no Brasil','treino','Qual foi uma causa da grande crise dos anos 1980 na América Latina?','["O excesso de dinheiro nos cofres públicos", "O fim do petróleo no mundo", "A dívida externa elevada e os juros altos", "A Segunda Guerra Mundial"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('hist-t41','historia','Transformações do capitalismo na América Latina e no Brasil','treino','No início do século XXI, os países latino-americanos que adotaram políticas neoliberais:','["Controlaram a inflação, mas não tiveram desenvolvimento social profundo e perderam postos de trabalho", "Acabaram com a pobreza", "Voltaram a ser colônias", "Passaram a viver com hiperinflação permanente"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('hist-t42','historia','Transformações do capitalismo na América Latina e no Brasil','treino','O que são empresas transnacionais?','["Empresas que pertencem ao governo", "Empresas com sede num país que atuam em vários outros países", "Cooperativas de pequenos agricultores", "Pequenos comércios de bairro"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('hist-t43','historia','Nova República e Neoliberalismo','treino','O Plano Cruzado, de 1986, no governo Sarney:','["Trocou a moeda e congelou preços e salários", "Criou o real", "Bloqueou o dinheiro das poupanças", "Privatizou a Petrobras"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('hist-t44','historia','Nova República e Neoliberalismo','treino','Quem eram os "fiscais do Sarney"?','["Militares que vigiavam o Congresso", "Deputados da Constituinte", "Auditores do FMI", "Cidadãos que conferiam se os preços congelados estavam sendo respeitados"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('hist-t45','historia','Nova República e Neoliberalismo','treino','Qual medida marcou o início do governo Collor, em 1990?','["O bloqueio, por 18 meses, do dinheiro das contas e poupanças", "A criação do Plano Real", "O congelamento com os \"fiscais do Sarney\"", "O programa Bolsa Família"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('hist-t46','historia','Nova República e Neoliberalismo','treino','Quem eram os "caras-pintadas"?','["Militares contra a abertura política", "Artistas da época da ditadura", "Eleitores que defendiam Collor", "Jovens que foram às ruas pedir o impeachment de Collor"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('hist-t47','historia','Nova República e Neoliberalismo','treino','O Plano Real, de 1994, usou como etapa de transição para a nova moeda:','["O cruzado novo", "O bloqueio das poupanças", "A URV (Unidade Real de Valor)", "O congelamento de preços"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('hist-t48','historia','Nova República e Neoliberalismo','treino','Fernando Henrique Cardoso venceu a eleição de 1994 principalmente por causa:','["Do sucesso do Plano Real contra a inflação", "Do impeachment de Itamar Franco", "Da campanha Diretas Já", "Da crise do apagão"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('hist-t49','historia','Nova República e Neoliberalismo','treino','A "crise do apagão" de 2001, no governo FHC, foi causada:','["Pela falta de investimentos e de chuvas para as hidrelétricas", "Por uma guerra com país vizinho", "Pela privatização da água", "Por terremotos no Sudeste"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('hist-t50','historia','Nova República e Neoliberalismo','treino','Fome Zero, Bolsa Família, Minha Casa Minha Vida e ProUni são programas de qual governo?','["Fernando Henrique Cardoso", "Fernando Collor", "Lula (2003–2010)", "José Sarney"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('hist-p01','historia','Módulo 13: Brasil, a encruzilhada da ditadura','prova','Qual episódio de 1975 levou diversos setores da sociedade a se unirem contra a tortura?','["O atentado do Riocentro", "A votação da emenda Dante de Oliveira", "As greves do ABC", "O assassinato do jornalista Vladimir Herzog"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('hist-p02','historia','Módulo 13: Brasil, a encruzilhada da ditadura','prova','Quais fatores internacionais ajudaram a abertura política no Brasil?','["A Segunda Guerra Mundial e a queda do nazismo", "A \"détente\" (diminuição das tensões da Guerra Fria) e a política de direitos humanos do presidente americano Jimmy Carter", "A Revolução Russa de 1917", "A independência dos Estados Unidos"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('hist-p03','historia','Módulo 13: Brasil, a encruzilhada da ditadura','prova','Qual é a ordem cronológica correta?','["Diretas Já → fim do AI-5 → eleição de Tancredo → Riocentro", "Fim do AI-5 → atentado do Riocentro → Diretas Já → eleição de Tancredo", "Riocentro → eleição de Tancredo → fim do AI-5 → Diretas Já", "Eleição de Tancredo → Diretas Já → Riocentro → fim do AI-5"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('hist-p04','historia','Nova República e Constituição de 1988','prova','Qual alternativa NÃO é uma característica da Constituição de 1988?','["Voto facultativo para analfabetos", "Racismo como crime inafiançável", "Direito dos quilombolas às terras que ocupam", "Censura prévia à imprensa"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('hist-p05','historia','Nova República e Constituição de 1988','prova','A Assembleia Nacional Constituinte foi instalada em:','["1964, no governo Castelo Branco", "1992, no governo Collor", "1987, no governo Sarney", "1979, no governo Figueiredo"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('hist-p06','historia','A conquista do protagonismo feminino','prova','O que a lei de cotas de gênero de 2009 trouxe para a política?','["Mínimo de 30% de candidaturas de cada sexo e recursos e propaganda para incentivar a participação feminina", "Metade das cadeiras do Congresso reservada às mulheres", "O direito de as mulheres votarem pela primeira vez", "A proibição de mulheres em ministérios"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('hist-p07','historia','A conquista do protagonismo feminino','prova','A chamada "primavera feminista" foi:','["Um movimento pelo fim do voto feminino", "Uma lei da ditadura militar", "Uma nova onda de protestos, com grande participação de mulheres, por igualdade de direitos e contra a violência", "Uma estação do ano dedicada às mulheres"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('hist-p08','historia','Questão indígena e questão do "campo negro"','prova','Qual é a sequência correta dos órgãos indigenistas do governo brasileiro?','["FUNAI, criada em 1910, e depois o SPI, em 1967", "SPI, criado em 1910, e depois a FUNAI, em 1967", "SPI e FUNAI, criados juntos em 1988", "Só a FUNAI, criada pela Constituição de 1988"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('hist-p09','historia','Questão indígena e questão do "campo negro"','prova','Por que é importante reconhecer as terras das comunidades quilombolas?','["Para garantir moradia, trabalho e a preservação da cultura dos descendentes dos quilombos", "Para transformar essas terras em fazendas de café", "Para levar essas comunidades para as cidades", "Não há importância, pois os quilombos acabaram"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('hist-p10','historia','Transformações do capitalismo na América Latina e no Brasil','prova','Qual é uma crítica feita às políticas neoliberais na América Latina?','["Vieram acompanhadas de perda de postos de trabalho e de pouco desenvolvimento social", "Aumentaram demais o tamanho do Estado", "Provocaram hiperinflação nos anos 2000", "Acabaram com todas as empresas transnacionais"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('hist-p11','historia','Nova República e Neoliberalismo','prova','Qual é a ordem correta dos presidentes depois de 1985?','["Collor → Sarney → FHC → Itamar → Lula", "Sarney → Itamar → Collor → Lula → FHC", "Sarney → Collor → Itamar → FHC → Lula", "Itamar → Sarney → Collor → FHC → Lula"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
